:root {
  --cyan: #4df3ff;
  --pink: #ff2fb0;
  --purple: #8b5cff;
  --amber: #ffb347;
  --bg: #05060f;
  --hud: rgba(220, 240, 255, 0.92);
  --mono: ui-monospace, "SFMono-Regular", "Cascadia Mono", Menlo, Consolas, monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--hud);
  font-family: var(--mono);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

#app { position: fixed; inset: 0; overflow: hidden; }

#game {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

/* ---------- HUD ---------- */
#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  padding: calc(14px + env(safe-area-inset-top)) calc(16px + env(safe-area-inset-right))
           calc(14px + env(safe-area-inset-bottom)) calc(16px + env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.label {
  font-size: 10px;
  letter-spacing: 0.28em;
  opacity: 0.55;
}

.score-box .score {
  font-size: clamp(26px, 5vw, 40px);
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.04em;
  color: #fff;
  text-shadow: 0 0 18px rgba(77, 243, 255, 0.65);
  font-variant-numeric: tabular-nums;
}

.score-box .best {
  margin-top: 4px;
  font-size: 10px;
  letter-spacing: 0.18em;
  color: rgba(180, 210, 255, 0.5);
}

.wave-box { text-align: center; margin-top: 2px; }
.wave-box .wave {
  font-size: clamp(20px, 3.4vw, 28px);
  font-weight: 700;
  line-height: 1.05;
  color: var(--cyan);
  text-shadow: 0 0 16px rgba(77, 243, 255, 0.5);
}

.icon-btn {
  pointer-events: auto;
  width: 44px;
  height: 44px;
  border-radius: 12px;
  border: 1px solid rgba(120, 200, 255, 0.25);
  background: rgba(10, 20, 40, 0.45);
  color: rgba(210, 235, 255, 0.85);
  font-family: var(--mono);
  font-size: 13px;
  letter-spacing: 0.1em;
  cursor: pointer;
  backdrop-filter: blur(6px);
  transition: background 0.15s, border-color 0.15s;
}
.icon-btn:hover { background: rgba(30, 60, 110, 0.55); border-color: rgba(77, 243, 255, 0.5); }

.combo {
  position: absolute;
  top: calc(86px + env(safe-area-inset-top));
  left: calc(18px + env(safe-area-inset-left));
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--amber);
  opacity: 0;
  transform: scale(0.8);
  transition: opacity 0.18s, transform 0.18s;
  text-shadow: 0 0 14px rgba(255, 179, 71, 0.7);
}
.combo.on { opacity: 1; transform: scale(1); }

.banner {
  position: absolute;
  left: 50%;
  top: 32%;
  transform: translate(-50%, -50%);
  text-align: center;
  opacity: 0;
  pointer-events: none;
}
.banner.show { animation: bannerPop 1.8s ease-out forwards; }
.banner-main {
  font-size: clamp(30px, 7vw, 64px);
  font-weight: 800;
  letter-spacing: 0.14em;
  color: #fff;
  text-shadow: 0 0 30px rgba(77, 243, 255, 0.85), 0 0 70px rgba(139, 92, 255, 0.6);
}
.banner-sub {
  margin-top: 6px;
  font-size: 11px;
  letter-spacing: 0.4em;
  color: rgba(200, 230, 255, 0.65);
}
@keyframes bannerPop {
  0%   { opacity: 0; transform: translate(-50%, -42%) scale(0.92); }
  12%  { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  72%  { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -56%) scale(1.02); }
}

.hud-bottom { display: flex; justify-content: center; }
.meters { width: min(520px, 74vw); display: grid; gap: 8px; }

.meter {
  position: relative;
  height: 16px;
  border-radius: 8px;
  background: rgba(120, 200, 255, 0.1);
  border: 1px solid rgba(120, 200, 255, 0.18);
  overflow: hidden;
}
.meter .fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  border-radius: 8px;
  transition: width 0.14s linear;
}
.meter.health .fill {
  background: linear-gradient(90deg, #1fd6a0, #4df3ff);
  box-shadow: 0 0 18px rgba(77, 243, 255, 0.5);
}
.meter.health.low .fill {
  background: linear-gradient(90deg, #ff3b6b, #ff8f4d);
  box-shadow: 0 0 18px rgba(255, 59, 107, 0.6);
}
.meter.dash { height: 10px; }

.meter span {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 9px;
  letter-spacing: 0.26em;
  color: rgba(255, 255, 255, 0.82);
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.8);
}
.meter.dash .fill { background: linear-gradient(90deg, var(--purple), var(--pink)); opacity: 0.9; }

/* ---------- Touch controls ---------- */
#touch { position: absolute; inset: 0; pointer-events: none; display: none; }
body.touch #touch { display: block; }

#stick {
  position: absolute;
  left: calc(22px + env(safe-area-inset-left));
  bottom: calc(64px + env(safe-area-inset-bottom));
  width: 112px;
  height: 112px;
  border-radius: 50%;
  pointer-events: auto;
  touch-action: none;
  background: radial-gradient(circle, rgba(77, 243, 255, 0.06), rgba(10, 20, 40, 0.22) 62%, transparent 72%);
}
.stick-ring {
  position: absolute;
  inset: 10px;
  border-radius: 50%;
  border: 1px solid rgba(120, 220, 255, 0.25);
  box-shadow: inset 0 0 24px rgba(77, 243, 255, 0.08);
}
#knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 46px;
  height: 46px;
  margin: -23px 0 0 -23px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(140, 250, 255, 0.95), rgba(30, 140, 220, 0.45));
  border: 1px solid rgba(200, 250, 255, 0.7);
  box-shadow: 0 0 22px rgba(77, 243, 255, 0.55);
  transition: transform 0.06s linear;
}
#dashBtn {
  position: absolute;
  right: calc(26px + env(safe-area-inset-right));
  bottom: calc(78px + env(safe-area-inset-bottom));
  width: 86px;
  height: 86px;
  border-radius: 50%;
  pointer-events: auto;
  touch-action: none;
  border: 1px solid rgba(255, 47, 176, 0.6);
  background: radial-gradient(circle, rgba(255, 47, 176, 0.28), rgba(20, 8, 30, 0.5));
  color: #ffd9f2;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  box-shadow: 0 0 26px rgba(255, 47, 176, 0.28);
}
#dashBtn:active { transform: scale(0.94); background: rgba(255, 47, 176, 0.4); }

/* ---------- Overlays ---------- */
.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: radial-gradient(circle at 50% 45%, rgba(10, 14, 38, 0.55), rgba(3, 4, 12, 0.9));
  backdrop-filter: blur(4px);
  transition: opacity 0.3s ease;
  z-index: 5;
}
.overlay.hidden { opacity: 0; pointer-events: none; }

.screen { display: none; flex-direction: column; align-items: center; text-align: center; max-width: 620px; }
.screen.active { display: flex; animation: screenIn 0.35s ease-out; }
@keyframes screenIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: none; }
}

.brand {
  font-size: clamp(46px, 12vw, 96px);
  font-weight: 900;
  line-height: 0.92;
  letter-spacing: 0.06em;
  color: #fff;
  text-shadow: 0 0 30px rgba(77, 243, 255, 0.5), 0 0 80px rgba(139, 92, 255, 0.45);
}
.brand span {
  display: block;
  background: linear-gradient(92deg, var(--cyan), var(--purple) 55%, var(--pink));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 22px rgba(255, 47, 176, 0.35));
}
.brand.small { font-size: clamp(34px, 8vw, 60px); letter-spacing: 0.16em; }
.brand.danger { color: #ff7d9c; text-shadow: 0 0 30px rgba(255, 47, 90, 0.6); }

.tagline {
  margin-top: 16px;
  font-size: clamp(11px, 2.2vw, 13px);
  line-height: 1.7;
  letter-spacing: 0.16em;
  color: rgba(190, 220, 255, 0.68);
}

.chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin: 26px 0 4px; }
.chip {
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid rgba(120, 200, 255, 0.2);
  background: rgba(20, 40, 80, 0.28);
  font-size: 9px;
  letter-spacing: 0.18em;
  color: rgba(180, 215, 255, 0.62);
}
.chip b { color: var(--cyan); font-weight: 700; }

.cta {
  margin-top: 28px;
  padding: 15px 54px;
  border-radius: 14px;
  border: 1px solid rgba(77, 243, 255, 0.55);
  background: linear-gradient(180deg, rgba(77, 243, 255, 0.18), rgba(139, 92, 255, 0.14));
  color: #eaffff;
  font-family: var(--mono);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.32em;
  text-indent: 0.32em;
  cursor: pointer;
  box-shadow: 0 0 34px rgba(77, 243, 255, 0.2), inset 0 0 24px rgba(77, 243, 255, 0.06);
  transition: transform 0.12s, box-shadow 0.2s, background 0.2s;
}
.cta:hover {
  transform: translateY(-1px);
  background: linear-gradient(180deg, rgba(77, 243, 255, 0.3), rgba(139, 92, 255, 0.22));
  box-shadow: 0 0 46px rgba(77, 243, 255, 0.35), inset 0 0 24px rgba(77, 243, 255, 0.12);
}
.cta:active { transform: scale(0.97); }

.hint { margin-top: 22px; font-size: 9px; line-height: 2; letter-spacing: 0.14em; color: rgba(170, 200, 240, 0.45); }
.hint b { font-weight: 700; }
.c-cyan { color: var(--cyan); }
.c-pink { color: var(--pink); }

.stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(110px, 1fr));
  gap: 10px;
  margin-top: 28px;
  width: min(380px, 80vw);
}
.stat {
  border: 1px solid rgba(120, 200, 255, 0.16);
  background: rgba(16, 28, 56, 0.35);
  border-radius: 12px;
  padding: 12px 8px;
}
.stat span { display: block; font-size: 8px; letter-spacing: 0.28em; color: rgba(170, 205, 255, 0.5); }
.stat b { display: block; margin-top: 6px; font-size: 22px; color: #fff; font-variant-numeric: tabular-nums; text-shadow: 0 0 14px rgba(77, 243, 255, 0.4); }

@media (max-width: 560px) {
  .hud-top { align-items: flex-start; }
  .meters { width: 78vw; }
  .banner { top: 28%; }
}

/* Hide touch UI on precise pointers regardless of touch capability */
@media (pointer: fine) {
  body.touch #touch { display: none; }
}

