input.newString:
function drawPickups(t) {
  for (const q of G.pickups) {
    const power = Boolean(q.power);
    const info = POWERUPS[q.type];
    const color = q.type === 'hp' ? COLORS.green : (info ? info.color : COLORS.pink);
    const R = power ? 17 : 14;
    const pulse = 1 + Math.sin(q.t * 5) * (power ? 0.1 : 0.12);
    const alpha = q.life < 3 ? (Math.sin(q.t * 14) * 0.35 + 0.65) : 1;
    ctx.save();
    ctx.translate(q.x, q.y);
    ctx.scale(pulse, pulse);
    ctx.globalAlpha = alpha;
    ctx.shadowColor = color;
    ctx.shadowBlur = power ? 26 : 20;
    ctx.strokeStyle = color;
    ctx.lineWidth = power ? 2 : 1.5;
    ctx.beginPath();
    ctx.arc(0, 0, R, 0, Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha = alpha * 0.2;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(0, 0, R, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = alpha;

    if (power) {
      ctx.save();
      ctx.rotate(t * 0.8);
      ctx.setLineDash([4, 6]);
      ctx.globalAlpha = alpha * 0.65;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(0, 0, R + 7, 0, Math.PI * 2);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }

    ctx.save();
    if (power) ctx.rotate(t * 1.4);
    ctx.fillStyle = '#ffffff';
    if (q.type === 'hp') {
      ctx.fillRect(-5, -1.6, 10, 3.2);
      ctx.fillRect(-1.6, -5, 3.2, 10);
    } else if (q.type === 'aegis') {
      ctx.beginPath();
      ctx.moveTo(0, -9);
      ctx.lineTo(8, -5);
      ctx.lineTo(8, 0);
      ctx.quadraticCurveTo(8, 7, 0, 10);
      ctx.quadraticCurveTo(-8, 7, -8, 0);
      ctx.lineTo(-8, -5);
      ctx.closePath();
      ctx.fill();
    } else if (q.type === 'triple') {
      ctx.beginPath();
      ctx.arc(-6, 4, 2.6, 0, Math.PI * 2);
      ctx.arc(0, -5, 2.6, 0, Math.PI * 2);
      ctx.arc(6, 4, 2.6, 0, Math.PI * 2);
      ctx.fill();
    } else if (q.type === 'nova') {
      ctx.beginPath();
      ctx.moveTo(0, -10);
      ctx.lineTo(2.7, -2.7);
      ctx.lineTo(10, 0);
      ctx.lineTo(2.7, 2.7);
      ctx.lineTo(0, 10);
      ctx.lineTo(-2.7, 2.7);
      ctx.lineTo(-10, 0);
      ctx.lineTo(-2.7, -2.7);
      ctx.closePath();
      ctx.fill();
    } else {
      ctx.beginPath();
      ctx.moveTo(2, -8);
      ctx.lineTo(-5, 1);
      ctx.lineTo(0, 1);
      ctx.lineTo(-2, 8);
      ctx.lineTo(5, -1);
      ctx.lineTo(0, -1);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    if (power && info) {
      ctx.font = '700 8px ui-monospace, Menlo, monospace';
      ctx.textAlign = 'center';
      ctx.fillStyle = color;
      ctx.globalAlpha = alpha * 0.9;
      ctx.fillText(info.label, 0, R + 17);
      ctx.textAlign = 'left';
    }
    ctx.restore();
  }
  ctx.globalAlpha = 1;
  ctx.shadowBlur = 0;
}

